from support import *
import time
def main():
    while not (HERE/'verification.json').exists():time.sleep(3)
    result=json.loads((HERE/'result.json').read_text(encoding='utf-8'));v=json.loads((HERE/'verification.json').read_text(encoding='utf-8'));assert v['status']=='PASS';gpu=json.loads((OUT/'gpu_done.json').read_text(encoding='utf-8'));gap=json.loads((HERE/'gap_verification.json').read_text(encoding='utf-8'))
    lines=['# 통계 단서 1–4 실험 결과','', '2026-10-03 집 코덱스. 사전 main8238144, family_k32, DIAG p_worse<.025/32 및 CI상한<0, 모든 시드×검증기 같은 개선 방향. 원본·제출물 변경 없음. 외부 정답을 내부 전문가·보정 학습에 사용하지 않음.','', '| 실험 | 검증 | RMSE 변화율 범위 | 개선 조건 | 판정 |','|---|---|---:|---:|---|']
    for arm in ['TBIAS','TGATE','ESTATE']:
        for name in ['DIAG10','A','B','EXT10','EXT12']:
            rows=[s for s in result['scores'] if s['arm']==arm and s['validator']==name]
            if not rows:continue
            ds=[s['delta_pct'] for s in rows];lines.append(f'| {arm} | {name} | {min(ds):+.4f}% ~ {max(ds):+.4f}% | {sum(x<0 for x in ds)}/{len(ds)} | {result["decisions"][arm]} |')
    lines+=['','## 무엇을 실행했나','', '1. **TBIAS:** BASE·CODEX·PFN 전체 혼합의 내부 검증 잔차를 8개 현재/과거 조건으로 보정. Ridge100, ±0.35℃, 저온 보호 gate 유지. 기존 구성원 잔차 학습과 구별해 전체 혼합 오차를 목표로 삼았다.','2. **ESTATE:** 계절EC v2의 내부 검증 잔차를 과거 공개 관측 일평균과 현재 예측 차이·과거 변화율로 보정. 관측 간격에 exp(−gap/6)를 적용하고 Ridge100으로0에 수축, ±0.15 제한. 현재/미래/다른 온실/다른 기록 구간의 정답을 상태 관측에 쓰지 않았다.','3. **TGATE:** 세 전문가를 함께 포함한 혼합 제곱오차를 선형 Ridge1000으로 학습. 기존 비중 쪽 수축, 각 비중 변화 ±0.10, 비음수·합1 투영, 저온 보호 유지. 게이트는 선형 MSE를 적합한 뒤 제약 투영하므로 제약 하의 전역 최적화를 수행했다는 주장은 하지 않는다.','4. **결측 블록 검증:** 모든 외부 학습 안에서 5일 묶음 중 매4번째를 내부 검증으로 만들고 ±1일 buffer 제거. 실제 평가 날짜 metadata의 직전 관측 간격과 비교하고 EC 보정기만 관측5일추가지연 스트레스 검사. 그 스트레스는 기준 전문가까지 새로 학습한 별도 검증이 아니다.','', '## 독립 검산과 재현','',f'- 원자료 라벨·math.fsum RMSE {len(v["score_cells"])}조건, 내부/외부 분할{v["split_checks"]}개, 회귀 정상방정식{v["coef_checks"]}개, 최종 혼합/보정식{v["mix_checks"]}개 PASS. 최대 계수 차{v["max_coef_gap"]:.3g}.',f'- 신규 내부 PFN 첫 문맥 완전 재학습 최대 예측 차{gpu["first_context_complete_retrain_maxdiff"]:.3g}. 모든 PFN 문맥이 inner fit에 속하고 inner query/outer query 정답은 포함하지 않음.',f'- 실제 평가 날짜metadata {gap["days"]}일/{gap["rows"]}행, 직전 관측 간격 중앙값{gap["median_past_gap"]}일·90%지점{gap["p90_past_gap"]}일. 별도CSV/scalar 검산 PASS. 평가 입력값/정답을 모델 적합에 사용하지 않음.','- 전체 코드·분할행·context행·계수·예측을 보존. GPU정밀도 가속 probe는 예측차 .00668335>1e-5로 미적용. 기존 TK2는 체크포인트 보존 후 자동 재개한다.','', '## 판단 경계','', '- 하나의 고정 내부 holdout을 사용했다. 완전 내부 Kfold나 독립 미사용 최종 holdout이 아니다. 메타 학습 전문가의 학습량이 outer 전문가보다 적어 학습량 변화에 따른 분포 차이가 남는다.','- 기존 온도 TF 전역 입력 rank 가중치와 반복된 검증 재사용의 한계가 남는다. CODEX726/727은 실질 예측이 같을 수 있고, PFN문맥 차이도 독립 데이터 증거가 아니다. 본페로니는 모든 적응적 탐색 편향을 제거하지 않는다.','- ESTATE의 특징과 잔차는 현재 예측을 빼는 항을 공유한다. 내부 상관만으로 추가 예측정보를 입증하지 않으며 외부 점수/방향/구간 일관성으로 판정한다. 과거 정답이 평가 시 합법적으로 관측 가능한 공개 학습 자료일 때만 적용 가능하다.','- 통과가 없으면 온도 W30G·EC 계절v2 유지. PASS_REQUIRES_GUARD_EL1은 추가 검증 전 채택하지 않으며 PUBLIC_PASS_NO_NEW_LOCK은 잠금을 재채점한 최종 채택이 아니다.','- scores.csv에 모든 시드/검증기·fold SD·DIAG CI와p, segments.csv에 농장/전후기·F47후기, ec_residual_diagnostics.csv에 내부 잔차·계수, gap_audit.csv/json에 외부·내부 관측 공백 기록. 새 제출/test예측/EC잠금 채점 없음.']
    (HERE/'결과보고서_v1.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(json.dumps(result['decisions']),flush=True)
if __name__=='__main__':main()
